  'The YourApp name, logo, design and content belong to us or our licensors. You may use the app for personal use only, and you may not copy, resell or modify any part of it without our written permission.': 'YourApp का नाम, लोगो, डिज़ाइन और सामग्री हमारी या हमारे लाइसेंसदाताओं की है। आप ऐप का उपयोग केवल निजी काम के लिए कर सकते हैं और हमारी लिखित अनुमति के बिना इसकी नकल, पुनर्विक्रय या बदलाव नहीं कर सकते।',
