  'We accept Visa and Mastercard cards, UPI apps such as Google Pay and PhonePe, and wallets like Paytm.': 'हम Visa और Mastercard कार्ड, Google Pay और PhonePe जैसे UPI ऐप और Paytm जैसे वॉलेट स्वीकार करते हैं।',
  'We collect the information you give us and some data created when you use the app.': 'हम आपके द्वारा दी गई जानकारी और ऐप इस्तेमाल करने पर बना कुछ डेटा एकत्र करते हैं।',
  'We do not sell your personal information. We share it only when needed to deliver our service.': 'हम आपकी निजी जानकारी नहीं बेचते। सेवा देने के लिए ज़रूरत पड़ने पर ही इसे साझा करते हैं।',
  'We have received your order ORD-78395 and started preparing it.': 'हमें आपका ऑर्डर ORD-78395 मिल गया है और हमने इसे तैयार करना शुरू कर दिया है।',
  'We may update these terms from time to time. When we make important changes, we will let you know in the app. Continuing to use the app means you accept the updated terms.': 'हम समय-समय पर इन शर्तों को अपडेट कर सकते हैं। महत्वपूर्ण बदलाव होने पर हम आपको ऐप में बताएंगे। ऐप का उपयोग जारी रखने का अर्थ है कि आप अपडेट की गई शर्तें स्वीकार करते हैं।',
  'We may update this policy from time to time. When we make important changes, we will notify you in the app and update the date at the top of this page.': 'हम समय-समय पर इस नीति को अपडेट कर सकते हैं। महत्वपूर्ण बदलाव होने पर हम आपको ऐप में सूचित करेंगे और इस पेज के ऊपर तारीख अपडेट करेंगे।',
  'We use encryption and access controls to protect your data. We keep your information for as long as your account is active or as needed to meet legal obligations, and delete or anonymise it afterwards.': 'हम आपके डेटा की सुरक्षा के लिए एन्क्रिप्शन और एक्सेस नियंत्रण का उपयोग करते हैं। हम आपकी जानकारी तब तक रखते हैं जब तक आपका खाता सक्रिय है या कानूनी दायित्वों के लिए आवश्यक है, और उसके बाद उसे हटाते या गुमनाम करते हैं।',
  'We use your information to run and improve our service.': 'हम आपकी जानकारी का उपयोग सेवा चलाने और बेहतर बनाने के लिए करते हैं।',
  'We will use your device’s GPS to detect the nearest delivery address.': 'हम निकटतम डिलीवरी पता खोजने के लिए आपके डिवाइस के GPS का उपयोग करेंगे।',
  'We work hard to keep the app running smoothly, but we cannot promise it will always be available or error free. To the extent allowed by law, we are not responsible for indirect or incidental losses arising from your use of the app.': 'हम ऐप को सुचारू रूप से चलाने की पूरी कोशिश करते हैं, लेकिन इसकी निरंतर उपलब्धता या त्रुटिरहित होने की गारंटी नहीं दे सकते। कानून द्वारा अनुमति की सीमा तक, ऐप के उपयोग से होने वाले अप्रत्यक्ष या आकस्मिक नुकसान के लिए हम ज़िम्मेदार नहीं हैं।',
