  'You are in control of your information.': 'आप अपनी जानकारी पर नियंत्रण रखते हैं।',
  'You are responsible for activity that happens under your account.': 'आपके खाते के तहत होने वाली गतिविधियों के लिए आप ज़िम्मेदार हैं।',
  'You are responsible for keeping your account safe.': 'अपने खाते को सुरक्षित रखना आपकी ज़िम्मेदारी है।',
  'You can cancel an order before it is marked as Preparing. After that, the items are packed and cannot be changed.': 'ऑर्डर को तैयार किया जा रहा है के रूप में चिह्नित किए जाने से पहले आप उसे रद्द कर सकते हैं। इसके बाद आइटम पैक हो जाते हैं और बदले नहीं जा सकते।',
  'You can edit your address in Profile > Saved Addresses. If the order is already out for delivery, I can ask the rider to update it.': 'आप प्रोफ़ाइल > सहेजे गए पते में अपना पता संपादित कर सकते हैं। यदि ऑर्डर डिलीवरी के लिए निकल गया है, तो मैं राइडर से इसे अपडेट करने को कह सकता हूं।',
  'You can pay with the methods shown at checkout, such as cards, UPI and wallets. Payments are processed by our payment partners, and you agree to their terms when you use them.': 'आप चेकआउट पर दिखाए गए तरीकों, जैसे कार्ड, UPI और वॉलेट से भुगतान कर सकते हैं। भुगतान हमारे साझेदार संसाधित करते हैं और उनका उपयोग करके आप उनकी शर्तों से सहमत होते हैं।',
  'You can stop using the app or delete your account anytime from Settings. We may suspend or close accounts that break these terms or are used for fraud or abuse.': 'आप कभी भी ऐप का उपयोग बंद कर सकते हैं या सेटिंग्स से खाता हटा सकते हैं। इन शर्तों का उल्लंघन करने या धोखाधड़ी/दुरुपयोग के लिए इस्तेमाल किए गए खातों को हम निलंबित या बंद कर सकते हैं।',
  'You can track your order live from My Orders. Share your order ID and I will check the status for you.': 'आप मेरे ऑर्डर से अपना ऑर्डर लाइव ट्रैक कर सकते हैं। अपना ऑर्डर आईडी साझा करें, मैं स्थिति जांच दूंगा।',
  'You confirm that you are allowed to use the payment method you add.': 'आप पुष्टि करते हैं कि जो भुगतान तरीका जोड़ते हैं, उसे इस्तेमाल करने की अनुमति आपके पास है।',
