  'If an item is missing, damaged or incorrect, report it from My Orders and we will refund or replace it after review. Approved refunds usually reach your original payment method within 5-7 business days.': 'ਜੇ ਕੋਈ ਆਈਟਮ ਗੁੰਮ, ਖ਼ਰਾਬ ਜਾਂ ਗਲਤ ਹੋਵੇ, ਤਾਂ ਮੇਰੇ ਆਰਡਰਾਂ ਵਿੱਚ ਦੱਸੋ। ਜਾਂਚ ਤੋਂ ਬਾਅਦ ਅਸੀਂ ਰਿਫੰਡ ਕਰਾਂਗੇ ਜਾਂ ਆਈਟਮ ਬਦਲਾਂਗੇ। ਮਨਜ਼ੂਰ ਰਿਫੰਡ ਆਮ ਤੌਰ ’ਤੇ 5-7 ਕਾਰੋਬਾਰੀ ਦਿਨਾਂ ਵਿੱਚ ਮੂਲ ਭੁਗਤਾਨ ਤਰੀਕੇ ’ਤੇ ਆ ਜਾਂਦੇ ਹਨ।',
