  'Warn when inventory drops below 5 units': 'ਸਟਾਕ 5 ਯੂਨਿਟ ਤੋਂ ਘਟਣ ’ਤੇ ਚੇਤਾਵਨੀ ਦਿਓ',
  'We Deliver Grocery at Your Doorstep': 'ਅਸੀਂ ਕਰਿਆਨਾ ਤੁਹਾਡੇ ਦਰਵਾਜ਼ੇ ਤੱਕ ਪਹੁੰਚਾਉਂਦੇ ਹਾਂ',
  'We accept Visa and Mastercard cards, UPI apps such as Google Pay and PhonePe, and wallets like Paytm.': 'ਅਸੀਂ Visa ਅਤੇ Mastercard ਕਾਰਡ, Google Pay ਅਤੇ PhonePe ਵਰਗੀਆਂ UPI ਐਪਾਂ ਅਤੇ Paytm ਵਰਗੇ ਵਾਲਿਟ ਸਵੀਕਾਰ ਕਰਦੇ ਹਾਂ।',
  'We collect the information you give us and some data created when you use the app.': 'ਅਸੀਂ ਤੁਹਾਡੇ ਵੱਲੋਂ ਦਿੱਤੀ ਜਾਣਕਾਰੀ ਅਤੇ ਐਪ ਵਰਤਣ ਸਮੇਂ ਬਣਿਆ ਕੁਝ ਡੇਟਾ ਇਕੱਠਾ ਕਰਦੇ ਹਾਂ।',
  'We do not sell your personal information. We share it only when needed to deliver our service.': 'ਅਸੀਂ ਤੁਹਾਡੀ ਨਿੱਜੀ ਜਾਣਕਾਰੀ ਨਹੀਂ ਵੇਚਦੇ। ਸੇਵਾ ਦੇਣ ਲਈ ਲੋੜ ਪੈਣ ’ਤੇ ਹੀ ਇਸਨੂੰ ਸਾਂਝਾ ਕਰਦੇ ਹਾਂ।',
  'We have received your order ORD-78395 and started preparing it.': 'ਸਾਨੂੰ ਤੁਹਾਡਾ ਆਰਡਰ ORD-78395 ਮਿਲ ਗਿਆ ਹੈ ਅਤੇ ਅਸੀਂ ਇਸਨੂੰ ਤਿਆਰ ਕਰਨਾ ਸ਼ੁਰੂ ਕਰ ਦਿੱਤਾ ਹੈ।',
  'We may update these terms from time to time. When we make important changes, we will let you know in the app. Continuing to use the app means you accept the updated terms.': 'ਅਸੀਂ ਸਮੇਂ-ਸਮੇਂ ’ਤੇ ਇਨ੍ਹਾਂ ਸ਼ਰਤਾਂ ਨੂੰ ਅੱਪਡੇਟ ਕਰ ਸਕਦੇ ਹਾਂ। ਮਹੱਤਵਪੂਰਨ ਤਬਦੀਲੀਆਂ ਹੋਣ ’ਤੇ ਅਸੀਂ ਐਪ ਵਿੱਚ ਤੁਹਾਨੂੰ ਦੱਸਾਂਗੇ। ਐਪ ਵਰਤਦੇ ਰਹਿਣ ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਤੁਸੀਂ ਅੱਪਡੇਟ ਕੀਤੀਆਂ ਸ਼ਰਤਾਂ ਸਵੀਕਾਰ ਕਰਦੇ ਹੋ।',
  'We may update this policy from time to time. When we make important changes, we will notify you in the app and update the date at the top of this page.': 'ਅਸੀਂ ਸਮੇਂ-ਸਮੇਂ ’ਤੇ ਇਸ ਨੀਤੀ ਨੂੰ ਅੱਪਡੇਟ ਕਰ ਸਕਦੇ ਹਾਂ। ਮਹੱਤਵਪੂਰਨ ਤਬਦੀਲੀਆਂ ਕਰਨ ’ਤੇ ਅਸੀਂ ਐਪ ਵਿੱਚ ਤੁਹਾਨੂੰ ਸੂਚਿਤ ਕਰਾਂਗੇ ਅਤੇ ਇਸ ਪੰਨੇ ਦੇ ਉੱਪਰ ਤਾਰੀਖ ਅੱਪਡੇਟ ਕਰਾਂਗੇ।',
  'We use encryption and access controls to protect your data. We keep your information for as long as your account is active or as needed to meet legal obligations, and delete or anonymise it afterwards.': 'ਤੁਹਾਡੇ ਡੇਟਾ ਦੀ ਰੱਖਿਆ ਲਈ ਅਸੀਂ ਇਨਕ੍ਰਿਪਸ਼ਨ ਅਤੇ ਪਹੁੰਚ ਨਿਯੰਤਰਣ ਵਰਤਦੇ ਹਾਂ। ਤੁਹਾਡਾ ਖਾਤਾ ਸਰਗਰਮ ਰਹਿਣ ਜਾਂ ਕਾਨੂੰਨੀ ਲੋੜਾਂ ਪੂਰੀਆਂ ਕਰਨ ਤੱਕ ਜਾਣਕਾਰੀ ਰੱਖਦੇ ਹਾਂ, ਫਿਰ ਇਸਨੂੰ ਮਿਟਾ ਜਾਂ ਅਗਿਆਤ ਕਰ ਦਿੰਦੇ ਹਾਂ।',
  'We use your information to run and improve our service.': 'ਅਸੀਂ ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਆਪਣੀ ਸੇਵਾ ਚਲਾਉਣ ਅਤੇ ਬਿਹਤਰ ਬਣਾਉਣ ਲਈ ਵਰਤਦੇ ਹਾਂ।',
  'We will use your device’s GPS to detect the nearest delivery address.': 'ਨੇੜਲਾ ਡਿਲਿਵਰੀ ਪਤਾ ਲੱਭਣ ਲਈ ਅਸੀਂ ਤੁਹਾਡੇ ਡਿਵਾਈਸ ਦਾ GPS ਵਰਤਾਂਗੇ।',
  'We work hard to keep the app running smoothly, but we cannot promise it will always be available or error free. To the extent allowed by law, we are not responsible for indirect or incidental losses arising from your use of the app.': 'ਅਸੀਂ ਐਪ ਨੂੰ ਸੁਚਾਰੂ ਚਲਾਉਣ ਦੀ ਪੂਰੀ ਕੋਸ਼ਿਸ਼ ਕਰਦੇ ਹਾਂ, ਪਰ ਹਮੇਸ਼ਾ ਉਪਲਬਧ ਜਾਂ ਗਲਤੀ-ਰਹਿਤ ਹੋਣ ਦੀ ਗਾਰੰਟੀ ਨਹੀਂ ਦੇ ਸਕਦੇ। ਕਾਨੂੰਨ ਵੱਲੋਂ ਮਨਜ਼ੂਰ ਹੱਦ ਤੱਕ, ਐਪ ਦੀ ਵਰਤੋਂ ਕਾਰਨ ਹੋਏ ਅਸਿੱਧੇ ਜਾਂ ਅਚਾਨਕ ਨੁਕਸਾਨ ਲਈ ਅਸੀਂ ਜ਼ਿੰਮੇਵਾਰ ਨਹੀਂ ਹਾਂ।',
