  'You are in control of your information.': 'ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ’ਤੇ ਤੁਹਾਡਾ ਨਿਯੰਤਰਣ ਹੈ।',
  'You are responsible for activity that happens under your account.': 'ਤੁਹਾਡੇ ਖਾਤੇ ਹੇਠ ਹੋਣ ਵਾਲੀ ਸਰਗਰਮੀ ਲਈ ਤੁਸੀਂ ਜ਼ਿੰਮੇਵਾਰ ਹੋ।',
  'You are responsible for keeping your account safe.': 'ਆਪਣਾ ਖਾਤਾ ਸੁਰੱਖਿਅਤ ਰੱਖਣਾ ਤੁਹਾਡੀ ਜ਼ਿੰਮੇਵਾਰੀ ਹੈ।',
  'You can cancel an order before it is marked as Preparing. After that, the items are packed and cannot be changed.': 'ਆਰਡਰ ਨੂੰ ਤਿਆਰ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ ਵਜੋਂ ਦਰਸਾਉਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਸੀਂ ਇਸਨੂੰ ਰੱਦ ਕਰ ਸਕਦੇ ਹੋ। ਉਸ ਤੋਂ ਬਾਅਦ ਆਈਟਮਾਂ ਪੈਕ ਹੋ ਜਾਂਦੀਆਂ ਹਨ ਅਤੇ ਬਦਲੀਆਂ ਨਹੀਂ ਜਾ ਸਕਦੀਆਂ।',
  'You can edit your address in Profile > Saved Addresses. If the order is already out for delivery, I can ask the rider to update it.': 'ਤੁਸੀਂ ਪ੍ਰੋਫ਼ਾਈਲ > ਸੰਭਾਲੇ ਪਤੇ ਵਿੱਚ ਆਪਣਾ ਪਤਾ ਸੋਧ ਸਕਦੇ ਹੋ। ਜੇ ਆਰਡਰ ਡਿਲਿਵਰੀ ਲਈ ਨਿਕਲ ਗਿਆ ਹੈ, ਤਾਂ ਮੈਂ ਰਾਈਡਰ ਨੂੰ ਅੱਪਡੇਟ ਕਰਨ ਲਈ ਕਹਿ ਸਕਦਾ ਹਾਂ।',
  'You can pay with the methods shown at checkout, such as cards, UPI and wallets. Payments are processed by our payment partners, and you agree to their terms when you use them.': 'ਤੁਸੀਂ ਚੈੱਕਆਉਟ ’ਤੇ ਦਿਖਾਏ ਤਰੀਕਿਆਂ, ਜਿਵੇਂ ਕਾਰਡ, UPI ਅਤੇ ਵਾਲਿਟ ਨਾਲ ਭੁਗਤਾਨ ਕਰ ਸਕਦੇ ਹੋ। ਭੁਗਤਾਨ ਸਾਡੇ ਸਾਥੀ ਕਰਦੇ ਹਨ ਅਤੇ ਉਨ੍ਹਾਂ ਦੀ ਵਰਤੋਂ ਕਰਕੇ ਤੁਸੀਂ ਉਨ੍ਹਾਂ ਦੀਆਂ ਸ਼ਰਤਾਂ ਮੰਨਦੇ ਹੋ।',
  'You can stop using the app or delete your account anytime from Settings. We may suspend or close accounts that break these terms or are used for fraud or abuse.': 'ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਵੇਲੇ ਐਪ ਵਰਤਣਾ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ ਜਾਂ ਸੈਟਿੰਗਾਂ ਤੋਂ ਖਾਤਾ ਮਿਟਾ ਸਕਦੇ ਹੋ। ਇਨ੍ਹਾਂ ਸ਼ਰਤਾਂ ਦੀ ਉਲੰਘਣਾ ਜਾਂ ਧੋਖਾਧੜੀ/ਦੁਰਵਰਤੋਂ ਲਈ ਵਰਤੇ ਖਾਤੇ ਅਸੀਂ ਮੁਅੱਤਲ ਜਾਂ ਬੰਦ ਕਰ ਸਕਦੇ ਹਾਂ।',
