  'If an item is missing, damaged or incorrect, report it from My Orders and we will refund or replace it after review. Approved refunds usually reach your original payment method within 5-7 business days.': 'જો કોઈ આઇટમ ખૂટતી, ક્ષતિગ્રસ્ત અથવા ખોટી હોય, તો મારા ઓર્ડર્સમાંથી તેની જાણ કરો. સમીક્ષા પછી અમે રિફંડ કરીશું અથવા બદલી આપીશું. મંજૂર થયેલ રિફંડ સામાન્ય રીતે 5-7 કામકાજના દિવસોમાં મૂળ ચુકવણી પદ્ધતિમાં જમા થાય છે.',
  'If an item is unavailable or priced incorrectly, we may cancel or adjust that item and refund you for it.': 'જો કોઈ આઇટમ અનુપલબ્ધ હોય અથવા ખોટી કિંમતવાળી હોય, તો અમે તે આઇટમ રદ કરી શકીએ છીએ અને તેનું રિફંડ આપી શકીએ છીએ.',
