  'This will permanently delete your store, catalog, and past orders. This action cannot be reversed.': 'આનાથી તમારો સ્ટોર, કેટલોગ અને ભૂતકાળના ઓર્ડર કાયમ માટે કાઢી નાખવામાં આવશે. આ ક્રિયા પાછી વાળી શકાતી નથી.',
