  'To Pay': 'ચૂકવવાપાત્ર',
  'To communicate with you about your orders, account and customer service requests.': 'તમારા ઓર્ડર્સ, એકાઉન્ટ અને ગ્રાહક સેવા વિનંતીઓ વિશે તમારી સાથે વાતચીત કરવા માટે.',
  'To contact You: To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication.': 'તમારો સંપર્ક કરવા માટે: ઈમેઈલ, ફોન કૉલ્સ, એસએમએસ અથવા ઇલેક્ટ્રોનિક સંચારના અન્ય સ્વરૂપો દ્વારા તમારો સંપર્ક કરવા માટે.',
  'To manage Your Account: to manage Your registration as a user of the Service.': 'તમારું એકાઉન્ટ મેનેજ કરવા માટે: સેવાના વપરાશકર્તા તરીકે તમારી નોંધણી મેનેજ કરવા માટે.',
  'To manage Your requests: To attend and manage Your requests to Us.': 'તમારી વિનંતીઓનું સંચાલન કરવા માટે: અમારી સમક્ષ તમારી વિનંતીઓને પહોંચી વળવા અને મેનેજ કરવા માટે.',
  'To prevent fraud and keep your account secure.': 'છેતરપિંડી રોકવા અને તમારું એકાઉન્ટ સુરક્ષિત રાખવા માટે.',
  'To process orders, deliveries and refunds.': 'ઓર્ડર્સ, ડિલિવરી અને રિફંડની પ્રક્રિયા કરવા માટે.',
  'To process your orders and deliver the items you purchase.': 'તમારા ઓર્ડર પર પ્રક્રિયા કરવા અને તમે ખરીદેલી વસ્તુઓ પહોંચાડવા માટે.',
  'To provide You with news, special offers and general information about other goods, services and events which we offer.': 'અમે ઑફર કરીએ છીએ તેવા અન્ય સામાન, સેવાઓ અને ઇવેન્ટ્સ વિશેના સમાચાર, વિશેષ ઑફર્સ અને સામાન્ય માહિતી તમને પ્રદાન કરવા માટે.',
  'To provide and maintain our Service, including to monitor the usage of our Service.': 'અમારી સેવાનો ઉપયોગ મોનિટર કરવા સહિત અમારી સેવા પ્રદાન કરવા અને જાળવી રાખવા માટે.',
  'To send order updates, and offers if you have turned them on.': 'ઓર્ડર અપડેટ્સ અને જો તમે ચાલુ કર્યા હોય તો ઑફર્સ મોકલવા માટે.',
