  'We Deliver Grocery at Your Doorstep': 'અમે તમારા ઘર સુધી કરિયાણું પહોંચાડીએ છીએ',
  'We accept Visa and Mastercard cards, UPI apps such as Google Pay and PhonePe, and wallets like Paytm.': 'અમે Visa અને Mastercard કાર્ડ્સ, Google Pay અને PhonePe જેવી UPI ઍપ્લિકેશન્સ અને Paytm જેવા વૉલેટ્સ સ્વીકારીએ છીએ.',
  'We collect the information you give us and some data created when you use the app.': 'તમે અમને આપો છો તે માહિતી અને એપનો ઉપયોગ કરતી વખતે બનાવેલ ડેટા અમે એકત્રિત કરીએ છીએ.',
  'We do not sell your personal information. We share it only when needed to deliver our service.': 'અમે તમારી વ્યક્તિગત માહિતી વેચતા નથી. અમે તેને સેવા આપવા માટે જરૂરી હોય ત્યારે જ શેર કરીએ છીએ.',
  'We have received your order ORD-78395 and started preparing it.': 'અમને તમારો ઓર્ડર ORD-78395 મળ્યો છે અને અમે તેને તૈયાર કરવાનું શરૂ કર્યું છે.',
  'We may update these terms from time to time. When we make important changes, we will let you know in the app. Continuing to use the app means you accept the updated terms.': 'અમે સમય સમય પર આ શરતો અપડેટ કરી શકીએ છીએ. મોટા ફેરફારો થવા પર અમે તમને એપમાં જણાવીશું.',
  'We may update this policy from time to time. When we make important changes, we will notify you in the app and update the date at the top of this page.': 'અમે સમય સમય પર આ નીતિ અપડેટ કરી શકીએ છીએ. જ્યારે અમે મહત્વપૂર્ણ ફેરફારો કરીશું, ત્યારે અમે તમને એપ્લિકેશનમાં સૂચિત કરીશું.',
  'We use encryption and access controls to protect your data. We keep your information for as long as your account is active or as needed to meet legal obligations, and delete or anonymise it afterwards.': 'અમે તમારા ડેટાને સુરક્ષિત રાખવા માટે એન્ક્રિપ્શન અને એક્સેસ કંટ્રોલનો ઉપયોગ કરીએ છીએ. તમારું એકાઉન્ટ સક્રિય હોય ત્યાં સુધી અમે તમારી માહિતી રાખીએ છીએ.',
  'We use your information to run and improve our service.': 'અમે અમારી સેવા ચલાવવા અને સુધારવા માટે તમારી માહિતીનો ઉપયોગ કરીએ છીએ.',
  'We will use your device’s GPS to detect the nearest delivery address.': 'અમે નજીકનું ડિલિવરી સરનામું શોધવા માટે તમારા ડિવાઇસના GPS નો ઉપયોગ કરીશું.',
  'We work hard to keep the app running smoothly, but we cannot promise it will always be available or error free. To the extent allowed by law, we are not responsible for indirect or incidental losses arising from your use of the app.': 'અમે એપને સરળતાથી ચલાવવા સખત મહેનત કરીએ છીએ, પરંતુ અમે વચન આપી શકતા નથી કે તે હંમેશા ઉપલબ્ધ અથવા ભૂલ રહિત રહેશે.',
