  'You are in control of your information.': 'તમારી માહિતી પર તમારું નિયંત્રણ છે.',
  'You are responsible for activity that happens under your account.': 'તમારા એકાઉન્ટ હેઠળ થતી પ્રવૃત્તિ માટે તમે જવાબદાર છો.',
  'You are responsible for keeping your account safe.': 'તમારા એકાઉન્ટને સુરક્ષિત રાખવા માટે તમે જવાબદાર છો.',
  'You can cancel an order before it is marked as Preparing. After that, the items are packed and cannot be changed.': 'ઓર્ડરને તૈયારી તરીકે ચિહ્નિત કરવામાં આવે તે પહેલાં તમે તેને રદ કરી શકો છો. તે પછી વસ્તુઓ પેક થઈ જાય છે અને બદલી શકાતી નથી.',
  'You can edit your address in Profile > Saved Addresses. If the order is already out for delivery, I can ask the rider to update it.': 'તમે પ્રોફાઇલ > સાચવેલા સરનામામાં તમારું સરનામું સંપાદિત કરી શકો છો. જો ઓર્ડર પહેલેથી ડિલિવરી માટે નીકળી ગયો હોય, તો હું રાઇડરને અપડેટ કરવા કહી શકું છું.',
  'You can pay with the methods shown at checkout, such as cards, UPI and wallets. Payments are processed by our payment partners, and you agree to their terms when you use them.': 'તમે ચેકઆઉટ વખતે દર્શાવેલ પદ્ધતિઓ જેમ કે કાર્ડ્સ, UPI અને વૉલેટ્સ દ્વારા ચૂકવણી કરી શકો છો.',
  'You can stop using the app or delete your account anytime from Settings. We may suspend or close accounts that break these terms or are used for fraud or abuse.': 'તમે સેટિંગ્સમાંથી ગમે ત્યારે એપનો ઉપયોગ બંધ કરી શકો છો અથવા તમારું એકાઉન્ટ ડિલીટ કરી શકો છો.',
  'You can track your order live from My Orders. Share your order ID and I will check the status for you.': 'તમે માય ઓર્ડર્સ પરથી તમારા ઓર્ડરને લાઈવ ટ્રેક કરી શકો છો. તમારો ઓર્ડર ID શેર કરો અને હું તમારા માટે સ્ટેટસ ચેક કરીશ.',
  'You confirm that you are allowed to use the payment method you add.': 'તમે પુષ્ટિ કરો છો કે તમે ઉમેરો છો તે ચુકવણી પદ્ધતિનો ઉપયોગ કરવા માટે તમે અધિકૃત છો.',
  'You don’t have any': 'તમારી પાસે કોઈ નથી',
