  'This will permanently delete your store, catalog, and past orders. This action cannot be reversed.': 'यामुळे तुमचे स्टोअर, कॅटलॉग आणि मागील ऑर्डर्स कायमस्वरूपी हटवल्या जातील. ही कृती परत करता येणार नाही.',
  'This will permanently remove your profile, saved addresses and order history. This cannot be undone.': 'यामुळे तुमचे प्रोफाइल, जतन केलेले पत्ते आणि ऑर्डर इतिहास कायमचा काढून टाकला जाईल. हे पूर्ववत केले जाऊ शकत नाही.',
