  'We accept Visa and Mastercard cards, UPI apps such as Google Pay and PhonePe, and wallets like Paytm.': 'आम्ही Visa आणि Mastercard कार्ड्स, Google Pay आणि PhonePe सारखी UPI ॲप्स आणि Paytm सारखी वॉलेट्स स्वीकारतो.',
  'We collect the information you give us and some data created when you use the app.': 'तुम्ही आम्हाला देता ती माहिती आणि ॲप वापरताना तयार होणारा डेटा आम्ही गोळा करतो.',
  'We do not sell your personal information. We share it only when needed to deliver our service.': 'आम्ही तुमची वैयक्तिक माहिती विकत नाही. सेवा देण्यासाठी आवश्यक असल्यासच आम्ही ती शेअर करतो.',
  'We have received your order ORD-78395 and started preparing it.': 'आम्हाला तुमची ऑर्डर ORD-78395 मिळाली आहे आणि आम्ही ती तयार करण्यास सुरुवात केली आहे.',
  'We may update these terms from time to time. When we make important changes, we will let you know in the app. Continuing to use the app means you accept the updated terms.': 'आम्ही वेळोवेळी या अटी अद्यतनित करू शकतो. मोठे बदल झाल्यावर आम्ही तुम्हाला ॲपमध्ये कळवू.',
  'We may update this policy from time to time. When we make important changes, we will notify you in the app and update the date at the top of this page.': 'आम्ही वेळोवेळी हे धोरण अद्यतनित करू शकतो. महत्त्वाचे बदल झाल्यास आम्ही तुम्हाला ॲपमध्ये सूचित करू.',
  'We use encryption and access controls to protect your data. We keep your information for as long as your account is active or as needed to meet legal obligations, and delete or anonymise it afterwards.': 'आम्ही तुमच्या डेटाचे संरक्षण करण्यासाठी एन्क्रिप्शन आणि प्रवेश नियंत्रण वापरतो.',
  'We use your information to run and improve our service.': 'आम्ही आमची सेवा चालवण्यासाठी आणि सुधारण्यासाठी तुमची माहिती वापरतो.',
  'We will use your device’s GPS to detect the nearest delivery address.': 'जवळचा डिलिव्हरी पत्ता शोधण्यासाठी आम्ही तुमच्या डिव्हाइसचा GPS वापरू.',
  'We work hard to keep the app running smoothly, but we cannot promise it will always be available or error free. To the extent allowed by law, we are not responsible for indirect or incidental losses arising from your use of the app.': 'आम्ही ॲप सुरळीत चालवण्यासाठी काम करतो, पण ते नेहमी त्रुटीमुक्त असेल असे आश्वासन आम्ही देत नाही.',
