  'You are responsible for activity that happens under your account.': 'तुमच्या खात्याखाली होणाऱ्या सर्व घडामोडींसाठी तुम्ही जबाबदार आहात.',
  'You are responsible for keeping your account safe.': 'तुमचे खाते सुरक्षित ठेवण्यासाठी तुम्ही जबाबदार आहात.',
  'You can cancel an order before it is marked as Preparing. After that, the items are packed and cannot be changed.': 'तयारी सुरू होण्यापूर्वी तुम्ही ऑर्डर रद्द करू शकता. त्यानंतर वस्तू पॅक केल्या जातात आणि बदलता येत नाहीत.',
  'You can edit your address in Profile > Saved Addresses. If the order is already out for delivery, I can ask the rider to update it.': 'तुम्ही प्रोफाइल > जतन केलेले पत्ते मध्ये तुमचा पत्ता संपादित करू शकता. ऑर्डर आधीच डिलिव्हरीसाठी बाहेर पडली असल्यास, मी रायडरला अपडेट करण्यास सांगेन.',
  'You can pay with the methods shown at checkout, such as cards, UPI and wallets. Payments are processed by our payment partners, and you agree to their terms when you use them.': 'तुम्ही चेकआउटवर दाखवलेल्या पद्धती जसे की कार्ड्स, UPI आणि वॉलेट्सद्वारे पेमेंट करू शकता.',
  'You can stop using the app or delete your account anytime from Settings. We may suspend or close accounts that break these terms or are used for fraud or abuse.': 'तुम्ही सेटिंग्जमधून कधीही ॲप वापरणे थांबवू शकता किंवा तुमचे खाते हटवू शकता.',
  'You can track your order live from My Orders. Share your order ID and I will check the status for you.': 'तुम्ही माझ्या ऑर्डर्सवरून तुमची ऑर्डर थेट ट्रॅक करू शकता. तुमचा ऑर्डर आयडी शेअर करा आणि मी तुमच्यासाठी स्थिती तपासेन.',
  'You confirm that you are allowed to use the payment method you add.': 'तुम्ही जोडलेली पेमेंट पद्धत वापरण्याची तुम्हाला परवानगी आहे याची पुष्टी तुम्ही करता.',
