export const TRANSLATIONS: Partial<Record<LanguageCode, TranslationCatalog>> = {
  hi: hindi,
  pa: punjabi,
  gu: gujarati,
  mr: marathi,
};

export const translate = (language: LanguageCode, source: string): string => {
  if (!source || !language || language === 'en') {
    return source;
  }
  const catalog = TRANSLATIONS[language];
  if (!catalog) {
    return source;
  }

  // 1. Direct exact lookup
  if (catalog[source]) {
    return catalog[source];
  }

  // 2. Normalized smart quotes lookup (replace ’ and ‘ with ', “” with ")
  const normalizedQuotes = source
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[\u201C\u201D]/g, '"')
    .trim();
  if (catalog[normalizedQuotes]) {
    return catalog[normalizedQuotes];
  }

  // 3. Parentheses suffix pattern: e.g. "In Stock (24)" -> "स्टॉक में (24)"
  const parenMatch = normalizedQuotes.match(/^(.+?)\s*(\(\d+\))$/);
  if (parenMatch) {
    const base = parenMatch[1].trim();
    const suffix = parenMatch[2];
    if (catalog[base]) {
      return `${catalog[base]} ${suffix}`;
    }
  }

  // 4. Trailing colon, asterisk, or punctuation pattern: e.g. "Store ID: #TK-88" or "Mobile *"
  const punctMatch = normalizedQuotes.match(/^(.*?)([\s\:\*\•\-\–]+)$/);
  if (punctMatch) {
    const base = punctMatch[1].trim();
    const suffix = punctMatch[2];
    if (catalog[base]) {
      return `${catalog[base]}${suffix}`;
    }
  }

  // 5. Store ID prefix pattern: e.g. "Store ID: #TK-VB-8821"
  const storeIdMatch = normalizedQuotes.match(/^(Store ID\:?)\s*(.*)$/i);
  if (storeIdMatch) {
    const label = catalog['Store ID:'] ?? catalog['Store ID'] ?? 'स्टोर आईडी:';
    return `${label} ${storeIdMatch[2]}`;
  }

  // 6. Bullet-separated phrases: e.g. "Open • Accepting Orders"
  if (normalizedQuotes.includes(' • ')) {
    const parts = normalizedQuotes.split(' • ');
    const translatedParts = parts.map((part) => catalog[part.trim()] ?? part);
    if (translatedParts.some((tp, idx) => tp !== parts[idx])) {
      return translatedParts.join(' • ');
    }
  }

  // 7. Case-insensitive fallback
  const lower = normalizedQuotes.toLowerCase();
  for (const key of Object.keys(catalog)) {
    if (key.toLowerCase() === lower) {
      return catalog[key];
    }
  }

  return source;
};
